ACK测试代码：
``` bash
void Gray_Debug_ReadReg0_AckStep(void)
{
    u8 ack1;
    u8 ack2;
    u8 ack3;
    u8 dat;
    Uart1_SendString("\r\n========== READ REG0 ACK STEP ==========\r\n");
    I2C_Start();
    ack1 = I2C_WriteByte(GRAY_SENSOR_ADDR << 1);
    Uart1_SendString("Step1 Write device addr 0x");
    Uart1_SendHex8(GRAY_SENSOR_ADDR << 1);
    Uart1_SendString(" ACK = ");
    Uart1_SendHex8(ack1);
    Uart1_SendString("\r\n");
    if(ack1 != 0)
    {
        I2C_Stop();
        Uart1_SendString("Failed at Step1: device address no ACK.\r\n");
        Uart1_SendString("========================================\r\n");
        return;
    }
    ack2 = I2C_WriteByte(0x00);
    Uart1_SendString("Step2 Write register 0x00 ACK = ");
    Uart1_SendHex8(ack2);
    Uart1_SendString("\r\n");
    if(ack2 != 0)
    {
        I2C_Stop();
        Uart1_SendString("Failed at Step2: register address no ACK.\r\n");
        Uart1_SendString("========================================\r\n");
        return;
    }
    I2C_Start();
    ack3 = I2C_WriteByte((GRAY_SENSOR_ADDR << 1) | 0x01);
    Uart1_SendString("Step3 Write read addr 0x");
    Uart1_SendHex8((GRAY_SENSOR_ADDR << 1) | 0x01);
    Uart1_SendString(" ACK = ");
    Uart1_SendHex8(ack3);
    Uart1_SendString("\r\n");
    if(ack3 != 0)
    {
        I2C_Stop();
        Uart1_SendString("Failed at Step3: read address no ACK.\r\n");
        Uart1_SendString("========================================\r\n");
        return;
    }
    dat = I2C_ReadByte(0);
    I2C_Stop();
    Uart1_SendString("REG0 DATA = 0x");
    Uart1_SendHex8(dat);
    Uart1_SendString("\r\n");
    Uart1_SendString("========================================\r\n");
}
